@test
def test_csv2():
    assert close(fvals(rd(T2)[["x", "y"]]), E_r_plain)
    assert cols(rd(T2)) == E_r_plain_c
    assert dts(rd(T2)) == E_r_plain_t
    assert cols(pd.read_csv_string(T2, ",", 0, None, None, ["x", "z"])) == E_r_use_c
    assert dts(pd.read_csv_string(T2, ",", 0, None, None, ["x", "z"])) == E_r_use_t
    assert close(fvals(pd.read_csv_string(T2, ",", 0, None, None, None, 3)[["x", "y"]]), E_r_nrows)
