    assert dts(pd.read_csv_string(T2, ",", None, ["p", "q", "r"], None, None, None, 2)) == E_r_skip_t
    assert close(fvals(pd.read_csv_string(T2, ",", None, ["p", "q", "r"], None, None, None, 2)[["p", "q"]]), E_r_skip)
    assert str(pd.read_csv_string(T2, ",", 0, None, "x")) == E_r_idx
    assert str(pd.read_csv_string(T2, ",", 0, None, 0)) == E_r_idx0
    assert cols(pd.read_csv_string(T2, ",", 0, None, None, None, None, 0, {"x": "float64", "z": "str"})) == E_r_dtype_c
    assert dts(pd.read_csv_string(T2, ",", 0, None, None, None, None, 0, {"x": "float64", "z": "str"})) == E_r_dtype_t
    assert close(fvals(pd.read_csv_string(T2, ",", 0, None, None, None, None, 0, None, ["a", "6.5"])[["y"]]), E_r_na)
    assert cols(pd.read_csv_string(T2, ",", 0, None, None, None, None, 0, None, ["a", "6.5"])) == E_r_na_c
