    assert str(pd.read_csv_string(T2, ",", 0, None, None, None, None, 0, None, ["a", "6.5"])) == E_r_na_z
    assert cols(pd.read_csv_string(T1, ";", 0, None, None, None, None, 0, None, ["?"], ["when"], True, True, "#")) == E_r_big_c
    assert dts(pd.read_csv_string(T1, ";", 0, None, None, None, None, 0, None, ["?"], ["when"], True, True, "#")) == E_r_big_t
    assert str(pd.read_csv_string(T1, ";", 0, None, None, None, None, 0, None, ["?"], ["when"], True, True, "#")) == E_r_big_s
    assert str(pd.read_csv_string(T2, ",", 0, None, None, None, None, 0, None, None, None, False)) == E_r_nodef
    assert rd(T2).to_csv() == E_w_def
    assert rd(T2).to_csv(None, ",", "", None, None, True, False) == E_w_noidx
    assert rd(T2).to_csv(None, ";", "NULL", "%.3f", None, True, False) == E_w_sep
